def transform(grid):
    """Clear the rows and columns containing a 2x2 zero marker, except 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return out
    r, c = marker
    rows = {r, r + 1}
    cols = {c, c + 1}
    for i in range(h):
        for j in range(w):
            if (i in rows or j in cols) and grid[i][j] != 2:
                out[i][j] = 0
    return out

